import React, { useState, useEffect, use } from 'react';
import './AppMain.css'
import { User, Calendar, ClipboardPenLine, Plus, ArrowLeft, Trash, Trash2, LogIn, Check } from 'lucide-react';
import { useLocation, useNavigate } from 'react-router-dom';
import axios from 'axios'

function AppMain() {
  const location = useLocation();
  const navigate = useNavigate();
  const username = location.state?.username || "Admin";
  const [showMenu, setShowMenu] = useState(false);
  const [historial, setHistorial] = useState([]);
  const [active, setActive] = useState("registro");

  // Select de los nuevos registros
  const [proyects, setProyects] = useState([]);
  const [task, setTask] = useState([]);
  const [report, setReport] = useState([])

  useEffect(() => {
    axios.get('http://localhost:8081/api/history/proyect', {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      const normalizedData = res.data.map(p => ({
        ...p,
        completed: Number(p.complete)
      }));
      setProyects(normalizedData);
    }).catch(err => {
      console.error("Los proyectos no se han cargado:", err);
    })

    axios.get('http://localhost:8081/api/history/task', {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      const uniqueTask = Array.from(new Map(res.data.map(t => [t.task, t])).values());
      setTask(uniqueTask);
    }).catch(err => {
      console.log("Las tareas no se han cargado:", err);
    })

    axios.get('http://localhost:8081/api/history/report', {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      setReport(res.data);
    }).catch(err => {
      console.error("Los reportes no se han cargado:", err);
    })
  }, [])

  // Nuevo Registro
  const [showForm, setShowForm] = useState(false);
  const [formData, setFormData] = useState({
    username: username,
    proyect: '',
    task: '',
    hours: '',
    description: ''
  });

  const [formProyect, setFormProyect] = useState({
    proyect: '',
    description: '',
    complete: ''
  });

  const [formTask, setFormTask] = useState({
    task: ''
  })

  const [formReport, setFormReport] = useState({
    priority: '',
    company: '',
    location: '',
    date: new Date().toISOString().split('T')[0],
    description: ''
  })

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData({ ...formData, [name]: value });
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/history/create/history', formData, {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      alert(res.data);
      setShowForm(false);
      window.location.reload();
    }).catch(err => {
      console.error("Error al guardar el historial", err);
    })
  }

  // Crear y borrar Proyecto
  const handleChangeProyect = (e) => {
    const { name, value } = e.target;
    setFormProyect({ ...formProyect, [name]: value });
  };

  const handleSubmitProyect = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/history/create/proyect', formProyect, {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      alert(res.data);
      setShowForm(false);
      window.location.reload();
    }).catch(err => {
      console.error("Error al guardar proyecto", err);
    })
  }

  const handleDeleteProyect = (id) => {
    axios.delete(`http://localhost:8081/api/history/delete/proyect/${id}`, {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(() => {
      setProyects(prev => prev.filter(p => p.id !== id));
    }).catch(err => {
      console.error("Error al eliminar proyecto", err);
    });
  };

  const updateProyectStatus = (id, newStatus) => {
    axios.put(`http://localhost:8081/api/history/update/proyect/${id}`,
      { completed: newStatus ? 1 : 0 },
      {
        auth: {
          username: 'ventu',
          password: '123'
        }
      }
    ).then(res => {
      console.log('Proyecto actualizado:', res.data);
      // Actualizar el estado en local
      setProyects(prev =>
        prev.map(p =>
          p.id === id ? { ...p, completed: newStatus } : p
        )
      );
    }).catch(err => {
      console.error('Error al actualizar el estado del proyecto:', err);
    });
  };

  // Crear y borrar Tarea
  const handleChangeTask = (e) => {
    const { name, value } = e.target;
    setFormTask({ ...formTask, [name]: value });
  };

  const handleSubmitTask = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/history/create/task', formTask, {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      alert(res.data);
      setShowForm(false);
      window.location.reload();
    }).catch(err => {
      console.error("Error al guardad tarea", err);
    })
  }

  const handleDeleteTask = (id) => {
    axios.delete(`http://localhost:8081/api/history/delete/task/${id}`, {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(() => {
      setTask(prev => prev.filter(t => t.id !== id));
    }).catch(err => {
      console.error("Error al eliminar tarea", err);
    });
  };

  // Crear Reporte 
  const handleChangeReport = (e) => {
    const { name, value } = e.target;
    setFormReport({ ...formReport, [name]: value });
  }

  const handleSubmitReport = (e) => {
    e.preventDefault();
    axios.post('http://localhost:8081/api/history/create/report', formReport, {
      auth: {
        username: 'ventu',
        password: '123'
      }
    }).then(res => {
      alert(res.data);
      setShowForm(false);
      window.location.reload();
    }).catch(err => {
      console.error("Error al guardar el reporte", err);
    })
  }

  const handleCompleteReport = async (id) => {
    try {
      await axios.post(`http://localhost:8081/api/history/complete/report/${id}`, {}, {
        auth: {
          username: 'ventu',
          password: '123'
        }
      });

      // Eliminarlo del estado del frontend (sin recargar toda la página)
      setReport(prev => prev.filter(r => r.id !== id));
    } catch (error) {
      console.error("Error al completar el reporte:", error);
      alert("Hubo un error al completar el reporte.");
    }
  };


  // Cargar los datos al cargar la página
  useEffect(() => {
    axios.get('http://localhost:8081/api/history', {
      auth: {
        username: 'ventu',
        password: '123'
      }
    })
      .then(res => {
        setHistorial(res.data);
      })
      .catch(err => {
        console.error("Error al obtener historial:", err);
      });
  }, []);

  const toggleMenu = () => {
    setShowMenu(!showMenu);
  };

  const logout = () => {
    navigate("/");
  };


  return (
    <div className='Main'>
      <header className='Main-header'>
        <img src="/logoQuiros.png" />
        <div className='usuario' onClick={toggleMenu}>
          <User />
          <strong>{username}</strong>
        </div>
        {showMenu && (
          <div className='dropdown'>
            <button onClick={logout}>Cerrar Sesion</button>
          </div>
        )}
      </header>
      <main>
        <div className='Main-menu'>
          <button className={active === "registro" ? "active" : ""} onClick={() => setActive("registro")}><Calendar />Registro Horas</button>
          <button className={active === "reportes" ? "active" : ""} onClick={() => setActive("reportes")}><ClipboardPenLine />Reportes</button>
        </div>
        <div className='Main-body'>
          {active === "registro" && (
            <>
              <button onClick={() => setShowForm(true)}><Plus />Añadir registro</button>
              <button onClick={() => setActive("proyectos")}><Plus />Ver Proyectos</button>
              <button onClick={() => setActive("tareas")}><Plus />Ver Tareas</button>
              {showForm && (
                <div className='modal-overlay'>
                  <div className='modal'>
                    <h2>Nuevo Registro de Horas</h2>
                    <form onSubmit={handleSubmit}>
                      <select name='proyect' placeholder='Proyecto' value={formData.proyect} onChange={handleChange} required>
                        <option value="">Seleccion un proyecto</option>
                        {proyects.filter((proyec) => Number(proyec.completed) === 0)
                          .map((proyec) => (
                            <option key={proyec.id} value={proyec.id}>{proyec.proyect}</option>
                          ))}
                      </select>
                      <select name='task' placeholder='Tarea' value={formData.task} onChange={handleChange} required>
                        <option value="">Selecciona una tarea</option>
                        {task.map((tasks) => (
                          <option key={tasks.id} value={tasks.task}>{tasks.task}</option>
                        ))}
                      </select>
                      <input name='hours' placeholder='Horas' value={formData.hours} onChange={handleChange} required />
                      <textarea name='description' placeholder='Descripcion' value={formData.description} onChange={handleChange} required />
                      <button type='submit'>Guardar</button>
                      <button type='button' onClick={() => setShowForm(false)}>Cancelar</button>
                    </form>
                  </div>
                </div>
              )}
              <table className='table'>
                <thead>
                  <tr>
                    <td>Usuario</td>
                    <td>Proyecto</td>
                    <td>Tarea</td>
                    <td>Horas</td>
                    <td>Descripcion</td>
                  </tr>
                </thead>
                <tbody>
                  {[...historial].reverse().map((item, index) => (
                    <tr key={index}>
                      <td>{item.user}</td>
                      <td>{item.proyect}</td>
                      <td>{item.task}</td>
                      <td>{item.hours}</td>
                      <td>{item.description}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </>
          )}

          {active === "proyectos" && (
            <>
              <button onClick={() => setActive("registro")}><ArrowLeft /> Volver</button>
              <button onClick={() => setShowForm(true)}><Plus />Añadir Proyecto</button>
              {showForm && (
                <div className='modal-overlay'>
                  <div className='modal'>
                    <h2>Nuevo Proyecto</h2>
                    <form onSubmit={handleSubmitProyect}>
                      <input name='proyect' placeholder='Proyecto' value={formProyect.proyect} onChange={handleChangeProyect} required />
                      <input name='description' placeholder='Descripcion' value={formProyect.description} onChange={handleChangeProyect} required />
                      <button type='submit'>Guardar</button>
                      <button type='button' onClick={() => setShowForm(false)}>Cancelar</button>
                    </form>
                  </div>
                </div>
              )}
              <table className='table'>
                <thead>
                  <tr>
                    <td>Proyecto</td>
                    <td>Descripcion</td>
                    <td>Completar</td>
                    <td></td>
                  </tr>
                </thead>
                <tbody>
                  {proyects.map((proyec, index) => (
                    <tr key={index}>
                      <td>{proyec.proyect}</td>
                      <td>{proyec.description}</td>
                      <td><input type="checkbox" checked={proyec.completed === 1} onChange={() => updateProyectStatus(proyec.id, Number(proyec.completed) === 1 ? 0 : 1)}></input></td>
                      <td><button onClick={() => handleDeleteProyect(proyec.id)}><Trash2 /></button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </>
          )}

          {active === "tareas" && (
            <>
              <button onClick={() => setActive("registro")}><ArrowLeft /> Volver</button>
              <button onClick={() => setShowForm(true)}><Plus />Añadir Tarea</button>
              {showForm && (
                <div className='modal-overlay'>
                  <div className='modal'>
                    <h2>Nueva Tarea</h2>
                    <form onSubmit={handleSubmitTask}>
                      <input name="task" placeholder='Tarea' value={formTask.task} onChange={handleChangeTask} required />
                      <button type='submit'>Guardar</button>
                      <button type='button' onClick={() => setShowForm(false)}>Cancelar</button>
                    </form>
                  </div>
                </div>
              )}
              <table className='table'>
                <thead>
                  <tr>
                    <td>Tarea</td>
                    <td></td>
                  </tr>
                </thead>
                <tbody>
                  {task.map((tarea, index) => (
                    <tr key={index}>
                      <td>{tarea.task}</td>
                      <td><button onClick={() => handleDeleteTask(tarea.id)}><Trash2 /></button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </>
          )}

          {active === "reportes" && (
            <>
              <button><LogIn></LogIn>Ver Logs</button>
              <button onClick={() => setShowForm(true)}><Plus />Añadir reporte</button>
              {showForm && (
                <div className='modal-overlay'>
                  <div className='modal'>
                    <h2>Nuevo Reporte</h2>
                    <form onSubmit={handleSubmitReport}>
                      <input name='company' placeholder='Empresa' value={formReport.company} onChange={handleChangeReport} required />
                      <input name='location' placeholder='Ubicación' value={formReport.location} onChange={handleChangeReport} required />
                      <div className='priority-row'>
                        <span className='priority-label'>Prioridad:</span>
                        <div className='priority-selector'>
                          <div className={`priority-circle red ${formReport.priority === 'alta' ? 'selected' : ''}`} onClick={() => setFormReport({ ...formReport, priority: 'alta' })} title="Alta"></div>
                          <div className={`priority-circle yellow ${formReport.priority === 'media' ? 'selected' : ''}`} onClick={() => setFormReport({ ...formReport, priority: 'media' })} title='Media'></div>
                          <div className={`priority-circle green ${formReport.priority === 'baja' ? 'selected' : ''}`} onClick={() => setFormReport({ ...formReport, priority: 'baja' })} title='Baja'></div>
                        </div>
                      </div>
                      <input type='hidden' name='date' value={formReport.date} />
                      <textarea name='description' placeholder='Descripción' value={formReport.description} onChange={handleChangeReport} />
                      <input type='hidden' name='priority' value={formReport.priority} />
                      <button type='submit'>Guardar</button>
                      <button type='button' onClick={() => setShowForm(false)}>Cancelar</button>
                    </form>
                  </div>
                </div>
              )}
              <table className='table'>
                <thead>
                  <tr>
                    <td></td>
                    <td>Empresa</td>
                    <td>Ubicación</td>
                    <td>Fecha</td>
                    <td>Descripción</td>
                    <td></td>
                    <td></td>
                    <td></td>
                  </tr>
                </thead>
                <tbody>
                  {report.map((reports, index) => (
                    <tr key={index}>
                      <td className={`priority-cell ${reports.priority === 'alta' ? 'priority-alta'
                          : reports.priority === 'media' ? 'priority-media'
                            : 'priority-baja'
                        }`} title={reports.priority}></td>
                      <td>{reports.company}</td>
                      <td>{reports.location}</td>
                      <td>{reports.date}</td>
                      <td>{reports.description}</td>
                      <td><button></button></td>
                      <td><button></button></td>
                      <td><button onClick={() => handleCompleteReport(reports.id)}><Check /></button></td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </>
          )}
        </div>
      </main>
    </div>
  );
}

export default AppMain;
